package com.dailytaskgenerator.notify;

import com.dailytaskgenerator.DailyTaskGeneratorConfig;
import java.util.ArrayDeque;
import java.util.Deque;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.WidgetNode;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetModalMode;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;

/**
 * Tells the player about completed tasks with a chat message and/or the game's own pop-up banner
 * (the one used for collection log items). Both are client-side only; nothing is sent to the server.
 * All methods must be called on the client thread.
 */
@Slf4j
@Singleton
public class TaskNotifier
{
	/**
	 * notification_display_init(title, text, colour): fills in the notification interface and starts
	 * its animation. Not in ScriptID; the animation scripts it runs are ScriptID.NOTIFICATION_START
	 * and NOTIFICATION_DELAY.
	 */
	private static final int NOTIFICATION_DISPLAY_INIT = 3343;
	/**
	 * Use the interface's default colour.
	 */
	private static final int DEFAULT_COLOUR = -1;
	/**
	 * Frames to wait for the banner to appear before treating the pop-up as broken.
	 */
	private static final int MAX_FRAMES_TO_APPEAR = 100;

	private final Client client;
	private final ClientThread clientThread;
	private final ChatMessageManager chatMessageManager;
	private final DailyTaskGeneratorConfig config;

	private final Deque<String[]> pendingPopups = new ArrayDeque<>();
	private WidgetNode showing;
	/**
	 * Set if the pop-up failed once, so the rest of the session falls back to chat.
	 */
	private boolean popupBroken;

	@Inject
	TaskNotifier(Client client, ClientThread clientThread, ChatMessageManager chatMessageManager, DailyTaskGeneratorConfig config)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.chatMessageManager = chatMessageManager;
		this.config = config;
	}

	public void taskCompleted(String taskTitle, long done, int total)
	{
		notify("Daily Task Complete!", "Daily task complete: ", taskTitle + " (" + done + "/" + total + ")");
	}

	public void allCompleted(int streak)
	{
		String days = streak == 1 ? "1 day" : streak + " days";
		notify("Daily Tasks Complete!", "All daily tasks complete! ", "Streak: " + days);
	}

	private void notify(String popupTitle, String chatPrefix, String text)
	{
		CompletionMessage mode = config.completionMessage();
		boolean popup = mode.isPopup() && !popupBroken;
		if (mode.isChat() || (mode.isPopup() && popupBroken))
		{
			chat(chatPrefix, text);
		}
		if (popup)
		{
			pendingPopups.add(new String[]{popupTitle, text, chatPrefix});
		}
	}

	private void chat(String prefix, String text)
	{
		String message = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append(prefix)
			.append(ChatColorType.NORMAL)
			.append(text)
			.build();
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(message)
			.build());
	}

	/**
	 * Shows the next queued pop-up once the notification slot is free, including of the game's own
	 * pop-ups. Call once per game tick.
	 */
	public void tick()
	{
		if (showing != null || pendingPopups.isEmpty())
		{
			return;
		}
		int component = notificationComponent();
		if (component == -1)
		{
			return;
		}
		if (client.getComponentTable().get(component) != null)
		{
			// The game is showing its own notification; ours waits its turn.
			return;
		}

		String[] next = pendingPopups.poll();
		try
		{
			WidgetNode node = client.openInterface(component, InterfaceID.NOTIFICATION_DISPLAY, WidgetModalMode.MODAL_CLICKTHROUGH);
			showing = node;
			client.runScript(NOTIFICATION_DISPLAY_INIT, next[0], next[1], DEFAULT_COLOUR);
			closeWhenFinished(node, next);
		}
		catch (RuntimeException e)
		{
			log.debug("Couldn't show notification pop-up; using chat messages instead", e);
			closeShowing();
			fallBackToChat(next);
		}
	}

	private void closeWhenFinished(WidgetNode node, String[] message)
	{
		int[] frames = {0};
		boolean[] appeared = {false};
		clientThread.invokeLater(() ->
		{
			if (showing != node)
			{
				return true;
			}
			Widget container = client.getWidget(InterfaceID.NotificationDisplay.CONTAINER);
			if (container != null && container.getWidth() > 0)
			{
				// Still animating or on screen.
				appeared[0] = true;
				return false;
			}
			if (!appeared[0] && ++frames[0] < MAX_FRAMES_TO_APPEAR)
			{
				return false;
			}
			closeShowing();
			if (!appeared[0])
			{
				log.debug("Notification pop-up never appeared; using chat messages instead");
				fallBackToChat(message);
			}
			return true;
		});
	}

	private void fallBackToChat(String[] message)
	{
		popupBroken = true;
		chat(message[2], message[1]);
		while (!pendingPopups.isEmpty())
		{
			String[] queued = pendingPopups.poll();
			chat(queued[2], queued[1]);
		}
	}

	private void closeShowing()
	{
		if (showing != null)
		{
			WidgetNode node = showing;
			showing = null;
			client.closeInterface(node, true);
		}
	}

	/**
	 * The current layout's notification slot, or -1 if this layout doesn't have one.
	 */
	private int notificationComponent()
	{
		switch (client.getTopLevelInterfaceId())
		{
			case InterfaceID.TOPLEVEL:
				return InterfaceID.Toplevel.NOTIFICATIONS;
			case InterfaceID.TOPLEVEL_OSRS_STRETCH:
				return InterfaceID.ToplevelOsrsStretch.NOTIFICATIONS;
			case InterfaceID.TOPLEVEL_PRE_EOC:
				return InterfaceID.ToplevelPreEoc.NOTIFICATIONS;
			case InterfaceID.TOPLEVEL_DISPLAY:
				return InterfaceID.ToplevelDisplay.NOTIFICATIONS;
			case InterfaceID.TOPLEVEL_OSM:
				return InterfaceID.ToplevelOsm.NOTIFICATIONS;
			default:
				return -1;
		}
	}

	/**
	 * Drops queued pop-ups and closes ours if it's open, e.g. on logout or shutdown.
	 */
	public void reset()
	{
		pendingPopups.clear();
		closeShowing();
	}
}

package com.dailytaskgenerator.player;

import com.dailytaskgenerator.data.DiaryRegion;
import com.dailytaskgenerator.data.DiaryTier;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import java.util.Set;
import lombok.Builder;
import lombok.Value;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/**
 * Immutable view of the player's state, so generators and tests never touch {@code Client}.
 */
@Value
@Builder(toBuilder = true)
public class PlayerSnapshot
{
	long accountHash;
	boolean members;
	int combatLevel;
	int questPoints;
	@Builder.Default
	Map<Skill, Integer> levels = Collections.emptyMap();
	@Builder.Default
	Map<Skill, Integer> experience = Collections.emptyMap();
	@Builder.Default
	Map<Quest, QuestState> questStates = Collections.emptyMap();
	/**
	 * Values of the CA_TASK_COMPLETED varps, in order.
	 */
	@Builder.Default
	int[] caCompletionVarps = new int[0];
	/**
	 * Completed diary tiers; regions with none completed may be absent.
	 */
	@Builder.Default
	Map<DiaryRegion, Set<DiaryTier>> completedDiaryTiers = Collections.emptyMap();

	public int getLevel(Skill skill)
	{
		return levels.getOrDefault(skill, 1);
	}

	public int getXp(Skill skill)
	{
		return experience.getOrDefault(skill, 0);
	}

	public QuestState getQuestState(Quest quest)
	{
		return questStates.getOrDefault(quest, QuestState.NOT_STARTED);
	}

	public boolean isQuestFinished(Quest quest)
	{
		return getQuestState(quest) == QuestState.FINISHED;
	}

	public boolean isDiaryTierComplete(DiaryRegion region, DiaryTier tier)
	{
		Set<DiaryTier> done = completedDiaryTiers.get(region);
		return done != null && done.contains(tier);
	}

	public boolean isCombatAchievementComplete(int taskId)
	{
		return isBitSet(caCompletionVarps, taskId);
	}

	public static boolean isBitSet(int[] varps, int taskId)
	{
		int index = taskId / 32;
		return taskId >= 0 && index < varps.length && (varps[index] & (1 << (taskId % 32))) != 0;
	}

	public static Map<Skill, Integer> emptySkillMap()
	{
		return new EnumMap<>(Skill.class);
	}
}

package com.dailytaskgenerator.player;

import com.dailytaskgenerator.data.CombatAchievementLoader;
import com.dailytaskgenerator.data.DiaryRegion;
import com.dailytaskgenerator.data.DiaryTier;
import java.util.EnumSet;
import java.util.Set;
import java.util.EnumMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.WorldType;
import net.runelite.api.gameval.VarPlayerID;

@Singleton
public class PlayerSnapshotBuilder
{
	private final Client client;

	@Inject
	PlayerSnapshotBuilder(Client client)
	{
		this.client = client;
	}

	/**
	 * Client thread only.
	 */
	public Map<DiaryRegion, Set<DiaryTier>> readDiaryTiers()
	{
		Map<DiaryRegion, Set<DiaryTier>> out = new EnumMap<>(DiaryRegion.class);
		for (DiaryRegion region : DiaryRegion.values())
		{
			Set<DiaryTier> done = EnumSet.noneOf(DiaryTier.class);
			for (DiaryTier tier : DiaryTier.values())
			{
				if (client.getVarbitValue(region.getVarbit(tier)) != 0)
				{
					done.add(tier);
				}
			}
			out.put(region, done);
		}
		return out;
	}

	/**
	 * Client thread only.
	 */
	public int[] readCaVarps()
	{
		int[] varps = new int[CombatAchievementLoader.COMPLETION_VARPS.length];
		for (int i = 0; i < varps.length; i++)
		{
			varps[i] = client.getVarpValue(CombatAchievementLoader.COMPLETION_VARPS[i]);
		}
		return varps;
	}

	/**
	 * Must be called on the client thread while logged in.
	 */
	public PlayerSnapshot build()
	{
		Map<Skill, Integer> levels = PlayerSnapshot.emptySkillMap();
		Map<Skill, Integer> xp = PlayerSnapshot.emptySkillMap();
		for (Skill skill : Skill.values())
		{
			if (skill == Skill.OVERALL)
			{
				continue;
			}
			levels.put(skill, client.getRealSkillLevel(skill));
			xp.put(skill, client.getSkillExperience(skill));
		}

		// Each getState call runs a client script, so this is only done when a snapshot is built
		// (login, generate, reroll), never per tick.
		Map<Quest, QuestState> quests = new EnumMap<>(Quest.class);
		for (Quest quest : Quest.values())
		{
			quests.put(quest, quest.getState(client));
		}

		Player local = client.getLocalPlayer();
		return PlayerSnapshot.builder()
			.accountHash(client.getAccountHash())
			.members(client.getWorldType().contains(WorldType.MEMBERS))
			.combatLevel(local != null ? local.getCombatLevel() : 3)
			.questPoints(client.getVarpValue(VarPlayerID.QP))
			.questStates(quests)
			.caCompletionVarps(readCaVarps())
			.completedDiaryTiers(readDiaryTiers())
			.levels(levels)
			.experience(xp)
			.build();
	}
}

package com.dailytaskgenerator.store;

import com.dailytaskgenerator.DailyTaskGeneratorConfig;
import com.dailytaskgenerator.data.CustomTask;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Keeps the imported custom tasks in the client config, shared by all accounts. The imported file
 * itself is only read once, at import time.
 */
@Slf4j
@Singleton
public class CustomTaskStore
{
	static final String KEY = "customTaskList";

	private final ConfigManager configManager;
	private final Gson gson;

	@Inject
	CustomTaskStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public List<CustomTask> load()
	{
		String json = configManager.getConfiguration(DailyTaskGeneratorConfig.GROUP, KEY);
		if (json == null || json.isEmpty())
		{
			return Collections.emptyList();
		}
		try
		{
			List<CustomTask> tasks = gson.fromJson(json, new TypeToken<List<CustomTask>>()
			{
			}.getType());
			return tasks == null ? Collections.emptyList() : tasks;
		}
		catch (JsonParseException e)
		{
			log.debug("Could not read saved custom tasks", e);
			return Collections.emptyList();
		}
	}

	public void save(List<CustomTask> tasks)
	{
		configManager.setConfiguration(DailyTaskGeneratorConfig.GROUP, KEY, gson.toJson(tasks));
	}
}

package com.dailytaskgenerator.store;

import com.dailytaskgenerator.DailyTaskGeneratorConfig;
import com.dailytaskgenerator.model.DailyTaskSet;
import com.dailytaskgenerator.model.Streak;
import com.dailytaskgenerator.model.TaskType;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.stream.Collectors;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Saves the day's tasks in the RuneScape-profile config, so each account (and world type,
 * e.g. seasonal) keeps its own list across relogs and client restarts.
 */
@Slf4j
@Singleton
public class TaskStore
{
	static final String TASK_SET_KEY = "taskSet";
	static final String STREAK_KEY = "streak";

	private final ConfigManager configManager;
	private final Gson gson;

	@Inject
	TaskStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	/**
	 * True once the logged-in account's profile is known; until then reads and writes would hit
	 * no profile.
	 */
	public boolean isProfileReady()
	{
		return configManager.getRSProfileKey() != null;
	}

	@Nullable
	public DailyTaskSet load()
	{
		String json = configManager.getRSProfileConfiguration(DailyTaskGeneratorConfig.GROUP, TASK_SET_KEY);
		return parse(gson, json);
	}

	public void save(DailyTaskSet set)
	{
		configManager.setRSProfileConfiguration(DailyTaskGeneratorConfig.GROUP, TASK_SET_KEY, gson.toJson(set));
	}

	public Streak loadStreak()
	{
		return parseStreak(gson, configManager.getRSProfileConfiguration(DailyTaskGeneratorConfig.GROUP, STREAK_KEY));
	}

	public void saveStreak(Streak streak)
	{
		configManager.setRSProfileConfiguration(DailyTaskGeneratorConfig.GROUP, STREAK_KEY, gson.toJson(streak));
	}

	static Streak parseStreak(Gson gson, @Nullable String json)
	{
		if (json == null || json.isEmpty())
		{
			return new Streak();
		}
		try
		{
			Streak streak = gson.fromJson(json, Streak.class);
			if (streak != null && streak.getLastDate() != null)
			{
				// Throws if the date is unreadable, which falls through to a fresh streak.
				LocalDate.parse(streak.getLastDate());
			}
			return streak == null ? new Streak() : streak;
		}
		catch (JsonParseException | DateTimeParseException e)
		{
			log.debug("Discarding unreadable saved streak", e);
			return new Streak();
		}
	}

	@Nullable
	static DailyTaskSet parse(Gson gson, @Nullable String json)
	{
		if (json == null || json.isEmpty())
		{
			return null;
		}
		DailyTaskSet set;
		try
		{
			set = gson.fromJson(json, DailyTaskSet.class);
		}
		catch (JsonParseException e)
		{
			log.debug("Discarding unreadable saved tasks", e);
			return null;
		}
		if (set == null || set.getDate() == null)
		{
			return null;
		}
		// Drop tasks from types or skills a later version no longer knows about.
		set.setTasks(set.getTasks() == null ? new ArrayList<>() : set.getTasks().stream()
			.filter(t -> t != null && t.getId() != null && t.getType() != null)
			.filter(t -> t.getType() != TaskType.SKILL || t.getSkill() != null)
			.filter(t -> t.getType() != TaskType.QUEST || t.getQuest() != null)
			.filter(t -> t.getType() != TaskType.COMBAT_ACHIEVEMENT || t.getCaTaskId() != null)
			.filter(t -> t.getType() != TaskType.DIARY || (t.getDiaryRegion() != null && t.getDiaryTier() != null))
			.collect(Collectors.toCollection(ArrayList::new)));
		return set;
	}
}

package com.dailytaskgenerator.track;

import com.dailytaskgenerator.data.DiaryRegion;
import com.dailytaskgenerator.data.DiaryTier;
import com.dailytaskgenerator.model.DailyTask;
import com.dailytaskgenerator.model.DailyTaskSet;
import com.dailytaskgenerator.model.TaskType;
import com.dailytaskgenerator.player.PlayerSnapshot;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

public final class TaskTracker
{
	private TaskTracker()
	{
	}

	/**
	 * Brings every task up to date with the player's current state, e.g. after loading saved tasks.
	 *
	 * @return true if any task changed
	 */
	public static boolean sync(DailyTaskSet set, PlayerSnapshot snapshot)
	{
		boolean changed = false;
		for (DailyTask task : set.getTasks())
		{
			if (task.getType() == TaskType.SKILL && task.getSkill() != null)
			{
				changed |= onXp(set, task.getSkill(), snapshot.getXp(task.getSkill()));
			}
		}
		changed |= onQuestStates(set, snapshot.getQuestStates());
		changed |= onCombatAchievementVarps(set, snapshot.getCaCompletionVarps());
		changed |= onDiaryTiers(set, snapshot.getCompletedDiaryTiers());
		return changed;
	}

	/**
	 * Marks diary tasks complete once their tier is done.
	 *
	 * @return true if any task changed
	 */
	public static boolean onDiaryTiers(DailyTaskSet set, Map<DiaryRegion, Set<DiaryTier>> completed)
	{
		boolean changed = false;
		for (DailyTask task : set.getTasks())
		{
			if (task.getType() != TaskType.DIARY || task.isCompleted() || task.getDiaryRegion() == null)
			{
				continue;
			}
			Set<DiaryTier> done = completed.get(task.getDiaryRegion());
			if (done != null && done.contains(task.getDiaryTier()))
			{
				task.setCompleted(true);
				changed = true;
			}
		}
		return changed;
	}

	/**
	 * Marks combat achievement tasks complete once their completion bit is set.
	 *
	 * @return true if any task changed
	 */
	public static boolean onCombatAchievementVarps(DailyTaskSet set, int[] varps)
	{
		boolean changed = false;
		for (DailyTask task : set.getTasks())
		{
			if (task.getType() == TaskType.COMBAT_ACHIEVEMENT && !task.isCompleted() && task.getCaTaskId() != null
				&& PlayerSnapshot.isBitSet(varps, task.getCaTaskId()))
			{
				task.setCompleted(true);
				changed = true;
			}
		}
		return changed;
	}

	/**
	 * Marks quest tasks complete once the quest is finished.
	 *
	 * @return true if any task changed
	 */
	public static boolean onQuestStates(DailyTaskSet set, Map<Quest, QuestState> states)
	{
		boolean changed = false;
		for (DailyTask task : set.getTasks())
		{
			if (task.getType() == TaskType.QUEST && !task.isCompleted() && task.getQuest() != null
				&& states.get(task.getQuest()) == QuestState.FINISHED)
			{
				task.setCompleted(true);
				changed = true;
			}
		}
		return changed;
	}

	/**
	 * Updates skill-task progress for a new XP total.
	 *
	 * @return true if any task changed
	 */
	public static boolean onXp(DailyTaskSet set, Skill skill, int xp)
	{
		boolean changed = false;
		for (DailyTask task : set.getTasks())
		{
			if (task.getType() != TaskType.SKILL || task.getSkill() != skill)
			{
				continue;
			}
			// Guard against the stat being reported before it has loaded.
			int progress = Math.max(0, Math.min(xp - task.getBaselineXp(), task.getTargetXp()));
			if (progress != task.getProgressXp())
			{
				task.setProgressXp(progress);
				changed = true;
			}
			if (!task.isCompleted() && progress >= task.getTargetXp())
			{
				task.setCompleted(true);
				changed = true;
			}
		}
		return changed;
	}
}

