package com.dailytaskgenerator.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import org.junit.Test;

public class StreakTest
{
	@Test
	public void firstDayStartsAtOne()
	{
		Streak s = new Streak().record("2026-11-05");
		assertEquals(1, s.getCurrent());
		assertEquals(1, s.getBest());
	}

	@Test
	public void consecutiveDaysExtend()
	{
		Streak s = new Streak().record("2026-11-05").record("2026-11-06").record("2026-11-07");
		assertEquals(3, s.getCurrent());
		assertEquals(3, s.getBest());
	}

	@Test
	public void sameDayTwiceIsNoOp()
	{
		Streak s = new Streak().record("2026-11-05");
		assertSame(s, s.record("2026-11-05"));
	}

	@Test
	public void gapResetsButKeepsBest()
	{
		Streak s = new Streak().record("2026-11-05").record("2026-11-06").record("2026-11-09");
		assertEquals(1, s.getCurrent());
		assertEquals(2, s.getBest());
	}

	@Test
	public void crossesMonthAndYearBoundaries()
	{
		assertEquals(2, new Streak().record("2026-11-30").record("2026-12-01").getCurrent());
		assertEquals(2, new Streak().record("2026-12-31").record("2027-01-01").getCurrent());
	}

	@Test
	public void currentAsOfExpiresAfterAMissedDay()
	{
		Streak s = new Streak().record("2026-11-05").record("2026-11-06");
		assertEquals(2, s.currentAsOf("2026-11-06"));
		// Still alive the next day, until that day ends unfinished.
		assertEquals(2, s.currentAsOf("2026-11-07"));
		assertEquals(0, s.currentAsOf("2026-11-08"));
		assertEquals(0, new Streak().currentAsOf("2026-11-08"));
	}
}

package com.dailytaskgenerator.store;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.dailytaskgenerator.model.DailyTask;
import com.dailytaskgenerator.model.DailyTaskSet;
import com.dailytaskgenerator.model.Streak;
import com.dailytaskgenerator.model.TaskType;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Skill;
import org.junit.Test;

public class TaskStoreTest
{
	// Plugin code uses the injected Gson; a plain one is equivalent for these types.
	private final Gson gson = new Gson();

	private static DailyTaskSet sample()
	{
		DailyTask t = new DailyTask();
		t.setId("skill:AGILITY");
		t.setType(TaskType.SKILL);
		t.setSkill(Skill.AGILITY);
		t.setTitle("Gain 5,000 Agility XP");
		t.setBaselineXp(12345);
		t.setTargetXp(5000);
		t.setManuallyCompleted(true);
		DailyTaskSet s = new DailyTaskSet();
		s.setDate("2026-11-05");
		s.setRerollCount(2);
		s.setTasks(new ArrayList<>(List.of(t)));
		return s;
	}

	@Test
	public void roundTrips()
	{
		DailyTaskSet loaded = TaskStore.parse(gson, gson.toJson(sample()));
		assertEquals(sample(), loaded);
	}

	@Test
	public void missingOrCorruptDataIsIgnored()
	{
		assertNull(TaskStore.parse(gson, null));
		assertNull(TaskStore.parse(gson, ""));
		assertNull(TaskStore.parse(gson, "{not json"));
		assertNull(TaskStore.parse(gson, "{\"rerollCount\":1}"));
	}

	@Test
	public void unknownTypesAndSkillsAreDropped()
	{
		String json = "{\"date\":\"2026-11-05\",\"tasks\":["
			+ "{\"id\":\"a\",\"type\":\"SOMETHING_NEW\"},"
			+ "{\"id\":\"b\",\"type\":\"SKILL\",\"skill\":\"NOT_A_SKILL\"},"
			+ "{\"id\":\"c\",\"type\":\"QUEST\",\"quest\":\"NOT_A_QUEST\"},"
			+ "{\"id\":\"d\",\"type\":\"COMBAT_ACHIEVEMENT\"},"
			+ "{\"id\":\"skill:MINING\",\"type\":\"SKILL\",\"skill\":\"MINING\",\"targetXp\":100}]}";
		DailyTaskSet set = TaskStore.parse(gson, json);
		assertEquals(1, set.getTasks().size());
		assertEquals("skill:MINING", set.getTasks().get(0).getId());
	}

	@Test
	public void nullTaskListBecomesEmpty()
	{
		DailyTaskSet set = TaskStore.parse(gson, "{\"date\":\"2026-11-05\",\"tasks\":null}");
		assertTrue(set.getTasks().isEmpty());
	}

	@Test
	public void streakRoundTripsAndToleratesBadData()
	{
		Streak streak = new Streak(4, 9, "2026-11-05");
		assertEquals(streak, TaskStore.parseStreak(gson, gson.toJson(streak)));
		assertEquals(new Streak(), TaskStore.parseStreak(gson, null));
		assertEquals(new Streak(), TaskStore.parseStreak(gson, "{bad"));
		assertEquals(new Streak(), TaskStore.parseStreak(gson, "{\"current\":2,\"lastDate\":\"yesterday\"}"));
	}
}

package com.dailytaskgenerator.track;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.dailytaskgenerator.model.DailyTask;
import com.dailytaskgenerator.model.DailyTaskSet;
import com.dailytaskgenerator.model.TaskType;
import com.dailytaskgenerator.player.PlayerSnapshot;
import java.util.Map;
import java.util.List;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import org.junit.Test;

public class TaskTrackerTest
{
	private static DailyTaskSet set()
	{
		DailyTask t = new DailyTask();
		t.setId("skill:MINING");
		t.setType(TaskType.SKILL);
		t.setSkill(Skill.MINING);
		t.setBaselineXp(1000);
		t.setTargetXp(500);
		DailyTaskSet s = new DailyTaskSet();
		s.setTasks(new java.util.ArrayList<>(List.of(t)));
		return s;
	}

	@Test
	public void tracksProgressAndCompletes()
	{
		DailyTaskSet s = set();
		assertTrue(TaskTracker.onXp(s, Skill.MINING, 1200));
		assertEquals(200, s.getTasks().get(0).getProgressXp());
		assertFalse(s.getTasks().get(0).isDone());

		assertTrue(TaskTracker.onXp(s, Skill.MINING, 1600));
		assertEquals(500, s.getTasks().get(0).getProgressXp());
		assertTrue(s.getTasks().get(0).isCompleted());
	}

	@Test
	public void ignoresOtherSkillsAndUnloadedStats()
	{
		DailyTaskSet s = set();
		assertFalse(TaskTracker.onXp(s, Skill.FISHING, 5000));
		assertFalse(TaskTracker.onXp(s, Skill.MINING, 0));
		assertEquals(0, s.getTasks().get(0).getProgressXp());
	}

	@Test
	public void syncRecomputesProgressFromSnapshot()
	{
		DailyTaskSet s = set();
		Map<Skill, Integer> xp = PlayerSnapshot.emptySkillMap();
		xp.put(Skill.MINING, 1700);
		PlayerSnapshot snap = PlayerSnapshot.builder().experience(xp).build();
		assertTrue(TaskTracker.sync(s, snap));
		assertEquals(500, s.getTasks().get(0).getProgressXp());
		assertTrue(s.getTasks().get(0).isCompleted());
		assertFalse(TaskTracker.sync(s, snap));
	}

	@Test
	public void questCompletesWhenFinished()
	{
		DailyTask q = new DailyTask();
		q.setId("quest:DORICS_QUEST");
		q.setType(TaskType.QUEST);
		q.setQuest(Quest.DORICS_QUEST);
		DailyTaskSet s = new DailyTaskSet();
		s.setTasks(new java.util.ArrayList<>(List.of(q)));

		assertFalse(TaskTracker.onQuestStates(s, Map.of(Quest.DORICS_QUEST, QuestState.IN_PROGRESS)));
		assertTrue(TaskTracker.onQuestStates(s, Map.of(Quest.DORICS_QUEST, QuestState.FINISHED)));
		assertTrue(q.isCompleted());
	}

	@Test
	public void combatAchievementCompletesWhenBitSet()
	{
		DailyTask ca = new DailyTask();
		ca.setId("ca:35");
		ca.setType(TaskType.COMBAT_ACHIEVEMENT);
		ca.setCaTaskId(35);
		DailyTaskSet s = new DailyTaskSet();
		s.setTasks(new java.util.ArrayList<>(List.of(ca)));

		assertFalse(TaskTracker.onCombatAchievementVarps(s, new int[]{-1, 0}));
		assertTrue(TaskTracker.onCombatAchievementVarps(s, new int[]{0, 1 << 3}));
		assertTrue(ca.isCompleted());
	}

	@Test
	public void diaryCompletesWhenTierDone()
	{
		DailyTask d = new DailyTask();
		d.setId("diary:FALADOR:EASY");
		d.setType(TaskType.DIARY);
		d.setDiaryRegion(com.dailytaskgenerator.data.DiaryRegion.FALADOR);
		d.setDiaryTier(com.dailytaskgenerator.data.DiaryTier.EASY);
		DailyTaskSet s = new DailyTaskSet();
		s.setTasks(new java.util.ArrayList<>(List.of(d)));

		assertFalse(TaskTracker.onDiaryTiers(s, Map.of()));
		assertTrue(TaskTracker.onDiaryTiers(s, Map.of(com.dailytaskgenerator.data.DiaryRegion.FALADOR,
			java.util.EnumSet.of(com.dailytaskgenerator.data.DiaryTier.EASY))));
		assertTrue(d.isCompleted());
	}
}

